function OverseaRenovaAestheticsPopup:SetGridShow()
    ---@type MaidCoffeePlayerComponent
    local maidCoffeePlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
    self.curIndex = maidCoffeePlayerComponent:GetCurEffectIndex()
    self.allVos = CfUtils.GetCf(AutoIds.IdSetting4112, "MaidCoffeeAestheticsVo", true)
    self.ScrollView:InitGridView(#self.allVos, Bind(self, self.OnGetItemByIndex))
    self.ScrollView:MovePanelToItemByRowColumn(self.curIndex - 1, 0)
end

function OverseaRenovaAestheticsPopup:OnGetItemByIndex(listView, index, row, column)
    if index < 0 then
        return nil
    end

    if #self.allVos < (index + 1) then
        return nil
    end

    local cell = listView:NewListViewItem(Cell)
    if not isNull(cell) then
        local env = CfUtils.GetLuaScr(cell,AestheticsPath)
        if env then
            local data = self.allVos[index + 1]
            env:RefreshShow(data,self.curIndex,index + 1)
        end
    end
    return cell
end

---美观度
function OverseaRenovaAestheticsPopup:SetAestheticsShow()
    ---@type MaidCoffeePlayerComponent
    local maidCoffeePlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
    local aestheticsNum = maidCoffeePlayerComponent:GetAestheticsNum()
    if self.commonAestheticsEnv then
        self.commonAestheticsEnv:RefreshShow(aestheticsNum,false,nil)
    end
end

function OverseaRenovaAestheticsPopup:OnBtnCloseClick()
    UIModule.CloseDialog(self.controller)
end

function OverseaRenovaAestheticsPopup:SetDesShow()
    local data = self.allVos[self.curIndex]
    local MaidCoffeeUtils     = import("Game.MaidCoffee.MaidCoffeeUtils")
    ---@type MaidCoffeeSkillVo
    local skillVo = MaidCoffeeUtils.GetMaidCoffeeSkillInfoVo(data.additionId)
    if skillVo then
        local desc = MaidCoffeeUtils.FillCoffeeSkillDescription(skillVo.decr, data.additionNum,nil,data.percentage)
        CfUtils.FillText(self.CurEffect,table.concat({localize("当前效果："),desc}))
    end

end

return OverseaRenovaAestheticsPopup